use std::{fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/absolute-norm176";
fn main(){let r=Path::new(R);let parent=fs::read_to_string("/home/ubuntu/src/zk-tools/zopro/crates/zopro-bn254/src/ifma8.rs").unwrap();let start=parent.find("    #[inline(always)]\n    fn product_cios<const FUSED: bool>").unwrap();let end=parent[start..].find("    /// Inputs must each be below p.").unwrap()+start;let mut body=parent[start..end].to_owned();
 let signature="fn product_cios<const FUSED: bool>(&self, b: &Self, c: &Self, d: &Self) -> Self {";assert_eq!(body.matches(signature).count(),1);body=body.replace(signature,"pub fn norm_canonical(&self, other: &Self) -> Self {\n        let b=self;let c=other;let d=other;const FUSED:bool=true;const MIXED:bool=true;");
 let final_block="            if FUSED && MIXED {\n                Self::reduce_fused(result)\n            } else {\n                Self(result, PhantomData)\n            }";assert_eq!(body.matches(final_block).count(),1);body=body.replace(final_block,"            Self(result, PhantomData)").replace("Self::splat","splat");assert!(!body.contains("Self::reduce"));
 let field=format!("//! Canonical absolute differences for sign-insensitive G2 norms.\nuse crate::{{ifma8::Ifma8,FpConfig}};use core::{{arch::x86_64::*,marker::PhantomData}};\nconst MASK:u64=(1u64<<52)-1;#[inline(always)]fn splat(x:u64)->__m512i{{unsafe{{_mm512_set1_epi64(x as i64)}}}}\nconst fn split(x:[u64;4])->[u64;5]{{[x[0]&MASK,((x[0]>>52)|(x[1]<<12))&MASK,((x[1]>>40)|(x[2]<<24))&MASK,((x[2]>>28)|(x[3]<<36))&MASK,x[3]>>16]}}\nimpl<C:FpConfig> Ifma8<C,true>{{\n{}\n{body}}}\n{}",fs::read_to_string(r.join("abs.rs.in")).unwrap(),fs::read_to_string(r.join("tests.rs.in")).unwrap());fs::write(r.join("field.rs"),field).unwrap();
 let old=Path::new("/home/ubuntu/src/zopro-perf-work/paired-fq2-pack176");let native=fs::read_to_string(old.join("native.rs")).unwrap().replace(old.to_str().unwrap(),R).replace("zopro_fq2_pair_pack","zopro_absolute_norm");fs::write(r.join("native.rs"),native).unwrap();
}
